      "number": 1,
      "title": "《泱泱华夏·择中建都》展览导语",
      "era": "当代展陈",
      "material": "展览环境",
      "provenance": "河南博物院基本陈列入口",
      "lead": "《泱泱华夏·择中建都》位于河南博物院基本陈列入口，以中原地理、都邑形成和文明延续为全展定下尺度。",
      "paragraphs": [
        {
          "heading": "身份与来处",
          "text": "《泱泱华夏·择中建都》位于河南博物院基本陈列入口，以中原地理、都邑形成和文明延续为全展定下尺度。 《泱泱华夏·择中建都》展览导语的出土或征集记录，勾勒出它进入河南博物院收藏的路径；未知处不另行补写。"
        },
        {
          "heading": "器形与工艺",
          "text": "墙面文字从“择中”切入，把早期聚落、王朝都城与历代制度放进同一条叙事线，而不是从某一件名品孤立起笔。展厅的轴线和文字层级把“择中建都”的叙事落到郑州这座都城上。"
        },
        {
          "heading": "历史现场",
          "text": "入口首先提出一个贯穿全展的问题：华夏文明为何在中原汇合，又如何借都城不断重组。它让随后出现的器物拥有共同的时间轴与空间坐标。"
        }
      ],
