      "title": "袋足陶斝",
      "era": "中原龙山文化",
      "material": "陶质炊器／温酒器",
      "provenance": "1959年河南偃师灰嘴出土",
      "lead": "1959年，袋足陶斝出土于河南偃师灰嘴，属于中原龙山文化。",
      "paragraphs": [
        {
          "heading": "身份与来处",
          "text": "1959年，袋足陶斝出土于河南偃师灰嘴，属于中原龙山文化。 灰嘴遗址的出土记录把这件袋足陶斝置回龙山文化的炊器组合；具体使用仍需结合残留物判断。"
        },
        {
          "heading": "器形与工艺",
          "text": "三只袋状足把火焰包围在器腹下方，既增加受热面积，也让器身能够独立支起。 泥胎中的颗粒与袋足转折先说明受火结构；它没有施釉，烧成痕迹应与器腹和足部合看。"
        },
        {
          "heading": "历史现场",
          "text": "斝形器通常同加热液体有关，具体盛用何物仍要结合残留物与同出器物判断。它显示龙山晚期陶器已把热工需要转化为稳定而鲜明的造型。"
        }
      ],
