      "provenance": "1977年河南汤阴白营遗址出土",
      "lead": "1977年，裸体人物纹高足镂孔灰陶盘出土于河南汤阴白营遗址，属于中原龙山文化。",
      "paragraphs": [
        {
          "heading": "身份与来处",
          "text": "1977年，裸体人物纹高足镂孔灰陶盘出土于河南汤阴白营遗址，属于中原龙山文化。 1977年河南汤阴白营遗址的出土信息把裸体人物纹高足镂孔灰陶盘放回具体年代，灰陶盘／高足镂孔器的器形与烧成线索仍需结合展签阅读。"
        },
        {
          "heading": "器形与工艺",
          "text": "浅盘下接高圈足，圈足以成组镂孔减轻体量；裸体人物以浅浮雕和刻划压进器表，身体形象与盘、足结构连成一体。 在1977年河南汤阴白营遗址的展柜光线下，看裸体人物纹高足镂孔灰陶盘的灰陶盘／高足镂孔器表面层次，边缘和背面也要一起核对。"
        },
        {
          "heading": "历史现场",
          "text": "高足盘可能用于陈放或仪式性展示，不能仅凭纹样断定某一种祭仪。人物图像与复杂镂孔同时出现，让它成为观察龙山时代身体观念和制陶技术的少见材料。"
        }
      ],
