      "title": "陶鬶",
      "era": "中原龙山文化",
      "material": "陶质水器／温器",
      "provenance": "河南漯河郾城郝家台遗址出土，河南省文物考古研究院藏",
      "lead": "陶鬶出土于河南漯河郾城郝家台遗址，现藏河南省文物考古研究院；年代为中原龙山文化。",
      "paragraphs": [
        {
          "heading": "身份与来处",
          "text": "陶鬶出土于河南漯河郾城郝家台遗址，现藏河南省文物考古研究院；年代为中原龙山文化。 郾城郝家台遗址留下的出土信息，使陶鬶可以与龙山文化的炊煮、倾注场景相连；更细的使用位置仍要看同坑材料。"
        },
        {
          "heading": "器形与工艺",
          "text": "长流、把手和三足共同解决倾注、持握与加热的问题，器身的重心因此带有明显方向。 陶鬶的泥胎、长流和三足转折一起决定受热与倾注的姿态；照片未显示的使用痕迹暂不补写。"
        },
        {
          "heading": "历史现场",
          "text": "鬶多同斟水或温液有关，也是龙山文化器物组合中极有辨识度的一类。郝家台材料把这种流动的器形放回中原地区聚落生活与礼仪实践之中。"
        }
      ],
