          "heading": "身份与来处",
          "text": "2006年，陶釜、陶灶在河南出土，属于仰韶文化；具体遗址尚待核定。 从河南出土，具体遗址在照片中未辨清的记录看，陶釜、陶灶的地点与年代相互校准，日常使用的判断因此有了边界。"
