          "heading": "身份与来处",
          "text": "1965年，镂孔高足红陶豆出土于河南淅川黄楝树遗址，属于屈家岭文化。 1965年河南淅川黄楝树遗址的出土信息把镂孔高足红陶豆放回具体年代，红陶盛食器的器形与烧成线索仍需结合展签阅读。"
