      "title": "白衣彩陶钵",
      "era": "仰韶文化",
      "material": "彩陶钵",
      "provenance": "1972年河南郑州大河村遗址出土",
      "lead": "1972年，白衣彩陶钵出土于河南郑州大河村遗址，属于仰韶文化。",
      "paragraphs": [
        {
          "heading": "身份与来处",
          "text": "1972年，白衣彩陶钵出土于河南郑州大河村遗址，属于仰韶文化。 大河村遗址的出土背景让白衣彩陶钵回到仰韶时期的餐饮器物序列；白衣和三角纹的具体意义不作越界推断。"
        },
        {
          "heading": "器形与工艺",
          "text": "器表先施浅色陶衣，再绘深色纹样，底色处理让图案更醒目。 白色陶衣覆盖在胎体之上，彩绘边缘与器壁转折显示了施彩次序；烧成温度仍无直接记录。"
        },
        {
          "heading": "历史现场",
          "text": "钵承担盛食，额外的施衣和彩绘工序则显示它并非最简便的日用制作。大河村彩陶保存了中原仰韶晚期成熟的色层控制与构图意识。"
        }
      ],
