      "id": "A-029",
      "number": 29,
      "title": "彩陶双连壶",
      "era": "仰韶文化",
      "material": "彩陶联体壶",
      "provenance": "1972年河南郑州大河村遗址出土",
      "lead": "1972年，彩陶双连壶出土于河南郑州大河村遗址，属于仰韶文化。",
      "paragraphs": [
        {
          "heading": "身份与来处",
          "text": "1972年，彩陶双连壶出土于河南郑州大河村遗址，属于仰韶文化。 1972年河南郑州大河村遗址的出土信息把彩陶双连壶放回具体年代，彩陶联体壶的器形与烧成线索仍需结合展签阅读。"
        },
        {
          "heading": "器形与工艺",
          "text": "两只壶体并联成一器，口、腹和连接处需要在湿坯阶段准确结合，彩绘又把双体纳入统一构图。 沿着彩陶双连壶的器壁、口沿和底部看，彩陶联体壶的泥胎怎样成型，1972年河南郑州大河村遗址的照片给出了一条清楚线索。"
        },
        {
          "heading": "历史现场",
          "text": "双连结构不以扩大容量见长，河南博物院把它解释为重要场合的共饮器；结盟等具体含义仍需考古组合支持。它以成双而相通的结构，把器物关系本身变成了表达。"
        }
      ],
