          "text": "1956年，花瓣纹彩陶钵出土于河南三门峡庙底沟遗址，属于仰韶文化。 1956年河南三门峡庙底沟遗址的出土信息把花瓣纹彩陶钵放回具体年代，彩陶钵的器形与烧成线索仍需结合展签阅读。"
