        {
          "heading": "器形与工艺",
          "text": "夹砂红陶器腹布置乳钉状突起，三足承担支撑和受火，表面处理兼具加固与装饰效果。 乳钉纹红陶鼎的胎色、收口和足部转折共同留下烧成线索，1977年河南新郑裴李岗遗址所见的红陶炊器更适合从受火与成型痕迹读起。"
        },
        {
          "heading": "历史现场",
          "text": "它用于炊煮，也是认识早期鼎形器演进的重要实例。“目前所见最早陶鼎”应保留“目前所见”的发现史范围，不能扩写为绝对的器类起源。"
        }
