      "lead": "栾川人牙齿化石的原件出土于河南栾川孙家洞遗址，年代约距今50万年；馆内所见为复制品。",
      "paragraphs": [
        {
          "heading": "身份与来处",
          "text": "栾川人牙齿化石的原件出土于河南栾川孙家洞遗址，年代约距今50万年；馆内所见为复制品。 栾川人牙齿化石（复制品）的可读性受刻痕、剥蚀与光线共同影响，局部照片比整面轮廓更能说明问题。"
        },
        {
          "heading": "器形与工艺",
          "text": "展柜中为复制品，牙冠与磨耗形态应以原件研究和正式测量为准。 栾川人牙齿化石（复制品）表面的不平整并非都来自年代，凿痕、修整与裂隙要分开观察。"
        },
        {
          "heading": "历史现场",
          "text": "牙齿可用于观察个体年龄、食物磨耗和人群形态特征，但不能由单枚复制品推演完整生活。孙家洞材料拓展了中原地区旧石器人类活动的时间与空间记录。"
        }
      ],
