          "text": "堆绳纹灰陶瓮出土于河南巩义稍柴遗址，属于夏代。 从河南巩义稍柴遗址出土的记录看，堆绳纹灰陶瓮的地点与年代相互校准，日常使用的判断因此有了边界。"
