      "paragraphs": [
        {
          "heading": "身份与来处",
          "text": "1990年，白陶爵出土于河南伊川南寨遗址，属于夏代。 1990年河南伊川南寨遗址的出土信息把白陶爵放回具体年代，白陶爵／饮器的器形与烧成线索仍需结合展签阅读。 白陶爵在1990年河南伊川南寨遗址的现场图组有2张照片，器物照和展签把名称与形制对应起来，白陶爵／饮器的细节以原图为准。"
        },
        {
          "heading": "器形与工艺",
          "text": "浅白细胎被塑成流、尾、鋬等复合部位，制作难度高于普通陶杯。 白陶爵把白陶爵／饮器的质地留在器壁起伏和边缘收束上，1990年河南伊川南寨遗址记录中的细部可与整体轮廓互相印证。"
        },
        {
          "heading": "历史现场",
          "text": "爵与饮酒、酌酒有关，更精细的白陶材质可能对应较特殊的使用场合。它使夏时期礼饮器的材质选择与形制试验同时可见。 对白陶爵而言，器形先于寓意，1990年河南伊川南寨遗址与白陶爵／饮器的同组线索共同限定可以说到哪一步。"
        }
      ],
