        "original": "妇好",
        "translation": "妇好之器；可理解为标明器主或受祭、受赠对象的署名。",
        "note": "两字铭文由河南博物院页面确认。它是名号，不是记事长铭；具体铸作、受赠或祭祀关系仍须结合整墓器物组合判断。",
