      "title": "原始瓷簋",
      "era": "西周",
      "material": "原始瓷盛食器",
      "provenance": "河南洛阳北窑西周墓地出土",
      "lead": "原始瓷簋出土于河南洛阳北窑西周墓地，属于西周。",
      "paragraphs": [
        {
          "heading": "身份与来处",
          "text": "原始瓷簋出土于河南洛阳北窑西周墓地，属于西周。 河南洛阳北窑西周墓地的出土信息把原始瓷簋放回具体年代，原始瓷盛食器的器形与烧成线索仍需结合展签阅读。"
        },
        {
          "heading": "器形与工艺",
          "text": "高温烧成的致密胎体与釉层被塑成簋形，材质不同于同时代青铜礼器。 把原始瓷簋放回河南洛阳北窑西周墓地的记录，胎釉厚薄与器形转折共同说明原始瓷盛食器的烧造特征。"
        },
        {
          "heading": "历史现场",
          "text": "簋用于盛放黍稷等食物，墓中随葬反映器类礼仪意义可以跨越材质。它使洛阳北窑墓地的礼器组合呈现出青铜、陶瓷并用的面貌。"
        }
      ],
