      "id": "A-093",
      "number": 93,
      "title": "透雕夔龙纹铜钺",
      "era": "西周",
      "material": "青铜兵器／仪仗器",
      "provenance": "河南洛阳北窑出土",
      "lead": "透雕夔龙纹铜钺出土于河南洛阳北窑，属于西周。",
      "paragraphs": [
        {
          "heading": "身份与来处",
          "text": "透雕夔龙纹铜钺出土于河南洛阳北窑，属于西周。 透雕夔龙纹铜钺的出土地点可定位在河南洛阳北窑，青铜兵器／仪仗器的器形与西周由此互相校准。 河南洛阳北窑为透雕夔龙纹铜钺留下2张图，正面、侧面和展签把青铜兵器／仪仗器的名称与轮廓放在同一组记录里。"
        },
        {
          "heading": "器形与工艺",
          "text": "宽刃上部以透雕夔龙纹减去实体，图案与受力结构需要同时计算。 透雕夔龙纹铜钺在河南洛阳北窑留下的器形资料，连接起青铜兵器／仪仗器的纹饰布局与边缘制作，局部观察不替代完整报告。"
        },
        {
          "heading": "历史现场",
          "text": "钺可用于军事、仪仗或权力象征，具体性质取决于墓葬位置与磨损。透雕工艺使兵器兼具威仪和观看性，是早周权力视觉的一种凝缩。"
        }
      ],
