      "era": "战国（前475—前221）",
      "material": "青铜酒器",
      "provenance": "1975年三门峡市上村岭出土",
      "lead": "展签记录，错银漆蟠螭纹铜方罍（附勺）属于战国（前475—前221），来源为1975年三门峡市上村岭出土。",
      "paragraphs": [
        {
          "heading": "身份与来处",
          "text": "展签记录，错银漆蟠螭纹铜方罍（附勺）属于战国（前475—前221），来源为1975年三门峡市上村岭出土。错银漆蟠螭纹铜方罍（附勺）在1975年三门峡市上村岭留下的组合线索，能约束青铜酒器在礼仪中的位置，单一纹饰只提供观察入口。"
        },
        {
          "heading": "器形与工艺",
          "text": "器物照片可见，错银漆蟠螭纹铜方罍（附勺）呈方腹有盖的大型盛酒器，盘曲蟠螭纹。 看错银漆蟠螭纹铜方罍（附勺），先把青铜酒器的器壁、耳部和纹饰分区拆开，再由1975年三门峡市上村岭的组合关系追问铸造先后。"
        },
        {
          "heading": "历史现场",
          "text": "罍储酒，附勺负责从深腹中取酒；器与勺保存在同一组合中，正好说明战国宴飨并非只看容器，也包括具体的取用程序。 错银漆蟠螭纹铜方罍（附勺）在1975年三门峡市上村岭留下的组合线索，能约束青铜酒器在礼仪中的位置，单一纹饰只提供观察入口。"
        }
      ],
