      "era": "战国（前475—前221）",
      "material": "青铜服饰构件",
      "provenance": "1975年三门峡市上村岭出土",
      "lead": "展签记录，错金嵌绿松石铜带钩属于战国（前475—前221），来源为1975年三门峡市上村岭出土。",
      "paragraphs": [
        {
          "heading": "身份与来处",
          "text": "展签记录，错金嵌绿松石铜带钩属于战国（前475—前221），来源为1975年三门峡市上村岭出土。错金嵌绿松石铜带钩的器形、青铜服饰构件与出土组合互相补充，礼仪位置不能只从一处纹饰推出。"
        },
        {
          "heading": "器形与工艺",
          "text": "器物本身，带钩用于扣合腰带，器表以金和绿松石嵌饰；小型构件仍具有鲜明的等级和装饰属性。 对照1975年三门峡市上村岭的出土信息，错金嵌绿松石铜带钩的纹带转折与边缘修整让青铜服饰构件的铸造过程有了可观察的层次。"
        },
        {
          "heading": "历史现场",
          "text": "错金嵌绿松石铜带钩扣合革带并装饰腰间，小型嵌饰直接显示战国贵族服用等级。 错金嵌绿松石铜带钩在1975年三门峡市上村岭留下的组合线索，能约束青铜服饰构件在礼仪中的位置，单一纹饰只提供观察入口。"
        }
      ],
