      "title": "秦始皇二十六年诏书铁权",
      "era": "秦始皇二十六年（前221）",
      "material": "铁权衡器",
      "provenance": "1986年宝丰县商酒务乡古城村出土",
      "lead": "秦始皇二十六年诏书铁权铸于统一六国的前221年，1986年在宝丰商酒务古城遗址出土；它不是墓中明器，而是秦制在地方城址内运行的衡器。",
      "paragraphs": [
        {
          "heading": "身份与来处",
          "text": "秦始皇二十六年诏书铁权铸于统一六国的前221年，1986年在宝丰商酒务古城遗址出土；它不是墓中明器，而是秦制在地方城址内运行的衡器。"
        },
        {
          "heading": "器形与工艺",
          "text": "器物照片中的铁权为平底实心半球体，顶部铸桥形钮，篆书诏文分行环列于表面；河南博物院资料记其生铁铸成，约重三十千克。"
        },
        {
          "heading": "历史现场",
          "text": "三十千克约合秦制一百二十斤即一石，秦始皇二十六年诏书铁权由此把统一度量衡的行政命令变成市场、赋税和仓储都能执行的重量标准。"
        }
      ],
