      "id": "b-012",
      "number": 134,
      "title": "白玉舞人佩",
      "era": "西汉（前206—25）",
      "material": "玉佩",
      "provenance": "永城市僖山汉墓出土",
      "lead": "展签记录，白玉舞人佩属于西汉（前206—25），来源为永城市僖山汉墓出土。",
      "paragraphs": [
        {
          "heading": "身份与来处",
          "text": "展签记录，白玉舞人佩属于西汉（前206—25），来源为永城市僖山汉墓出土。白玉舞人佩的来源记录指向永城市僖山汉墓，玉佩超出西汉（前206—25）与现有照片的推断暂不展开。"
        },
        {
          "heading": "器形与工艺",
          "text": "器物本身，白玉雕成相向舞人的轻薄佩饰，既用于佩戴，也把舞蹈姿态转化为随身图像。 白玉舞人佩的材质、穿孔与边缘要在多个角度下比较，单看正面会掩去厚度与磨痕。"
        },
        {
          "heading": "历史现场",
          "text": "白玉舞人佩悬系在衣带上随步移动，舞姿图像把宫廷表演和佩饰审美带入墓葬。 谈白玉舞人佩的身份表达，应把材质、佩戴组合和墓葬等级放在同一证据链里。"
        }
      ],
