      "title": "白玉勾连纹璏",
      "era": "西汉（前206—25）",
      "material": "玉剑饰",
      "provenance": "永城市僖山汉墓出土",
      "lead": "展签将白玉勾连纹璏定为西汉（前206—25），来源记作永城市僖山汉墓出土。",
      "paragraphs": [
        {
          "heading": "身份与来处",
          "text": "展签将白玉勾连纹璏定为西汉（前206—25），来源记作永城市僖山汉墓出土。白玉勾连纹璏属于玉剑饰；汉代佩玉和玉质兵器多服务于服饰、威仪或随葬，不能只按同形金属兵器的实战功能理解。"
        },
        {
          "heading": "器形与工艺",
          "text": "器形照片可见，白玉勾连纹璏呈弧面长方玉剑饰，连续勾连纹。 读白玉勾连纹璏的制作痕迹，侧面和背面的厚度、孔壁与刃缘同样重要。"
        },
        {
          "heading": "历史现场",
          "text": "白玉勾连纹璏固定或装饰剑鞘，玉质剑饰将武备、佩带和身份标志叠合在一起。 白玉勾连纹璏的礼仪含义要由同组玉饰和墓主人身份共同说明，不能只由纹样下结论。"
        }
      ],
