      "material": "玉礼器",
      "provenance": "永城市僖山汉墓出土",
      "lead": "展签记录，青玉勾连云纹戈属于西汉（前206—25），来源为永城市僖山汉墓出土。",
      "paragraphs": [
        {
          "heading": "身份与来处",
          "text": "展签记录，青玉勾连云纹戈属于西汉（前206—25），来源为永城市僖山汉墓出土。青玉勾连云纹戈在永城市僖山汉墓留下的组合线索，能约束玉礼器在礼仪中的位置，单一纹饰只提供观察入口。"
        },
        {
          "heading": "器形与工艺",
          "text": "器物本身，器形沿袭戈的轮廓，青玉表面饰勾连云纹；墓葬中的玉戈更侧重仪式和身份意义。 沿着青玉勾连云纹戈的接缝和纹饰边界看，玉礼器的范具分区逐渐显出轮廓，具体次序仍以永城市僖山汉墓记录为界。"
        },
        {
          "heading": "历史现场",
          "text": "青玉勾连云纹戈以兵器轮廓承担礼仪和随葬功能，玉材使武器形象转向身份与秩序的象征。 青玉勾连云纹戈在永城市僖山汉墓留下的组合线索，能约束玉礼器在礼仪中的位置，单一纹饰只提供观察入口。"
        }
      ],
