      "id": "b-027",
      "number": 149,
      "title": "金“关中侯印”",
      "era": "东汉（25—220）",
      "material": "金质印章",
      "provenance": "南阳市石桥镇出土",
      "lead": "展签记录，金“关中侯印”属于东汉（25—220），南阳市石桥镇出土。",
      "paragraphs": [
        {
          "heading": "身份与来处",
          "text": "展签记录，金“关中侯印”属于东汉（25—220），南阳市石桥镇出土。在同类器物中，小型金属或玉石构件直接参与佩带、车马、兵器或文书运作，尺寸虽小，却能清楚标示技术和身份。"
        },
        {
          "heading": "器形与工艺",
          "text": "近照把细部拍得较清楚，金“关中侯印”呈方形印体和篆书印面。 看金“关中侯印”，先把金质印章的器壁、耳部和纹饰分区拆开，再由南阳市石桥镇的组合关系追问铸造先后。"
        },
        {
          "heading": "历史现场",
          "text": "印章用于钤盖文书或封检，方寸之间把“关中侯”这一身份转化为可重复验证的凭信；金质又使它超出普通办公用品的等级。"
        }
      ],
