      "id": "b-034",
      "number": 156,
      "title": "黄釉三熊足陶盖鼎",
      "era": "西汉（前206—25）",
      "material": "釉陶器",
      "provenance": "征集",
      "lead": "展签记录，黄釉三熊足陶盖鼎属于西汉（前206—25），来源为征集。",
      "paragraphs": [
        {
          "heading": "身份与来处",
          "text": "展签记录，黄釉三熊足陶盖鼎属于西汉（前206—25），来源为征集。黄釉三熊足陶盖鼎的器形、釉陶器与出土组合互相补充，礼仪位置不能只从一处纹饰推出。"
        },
        {
          "heading": "器形与工艺",
          "text": "照片中鼎体有盖、双耳，下承三只熊形足；黄釉大面积覆盖器表，在凸起部位可见磨蚀和露胎。 黄釉三熊足陶盖鼎的胎体颗粒、边缘修整和表面颜色要分开读，征集记录只支持讨论釉陶器的制作线索。"
        },
        {
          "heading": "历史现场",
          "text": "盖鼎以陶质模拟可烹煮、盛食的鼎，三只熊足则把承重构件变成动物形象；因属征集品，它究竟是实用器还是明器只能保留为未决问题。"
        }
      ],
