      "material": "釉陶动物俑",
      "provenance": "项城市出土",
      "lead": "展签记录，绿釉立姿陶狗属于汉代（前206—220），来源为项城市出土。",
      "paragraphs": [
        {
          "heading": "身份与来处",
          "text": "展签记录，绿釉立姿陶狗属于汉代（前206—220），来源为项城市出土。项城市出土的出土信息把绿釉立姿陶狗放回具体年代，釉陶动物俑的器形与烧成线索仍需结合展签阅读。"
        },
        {
          "heading": "器形与工艺",
          "text": "器物本身，陶狗直立，通体施绿釉；这类动物明器通常与墓主人生活环境和护卫想象有关。 在项城市的展柜光线下，看绿釉立姿陶狗的釉陶动物俑表面层次，边缘和背面也要一起核对。"
        },
        {
          "heading": "历史现场",
          "text": "立姿陶狗把警戒状态固定为随葬形象，绿釉又使动物明器接近当时流行的釉陶陈设；项城出土信息为研究区域葬俗保留了坐标。"
        }
      ],
