      "id": "b-047",
      "number": 169,
      "title": "骆道明造像",
      "era": "北魏孝昌二年（526）",
      "material": "石质佛教造像",
      "provenance": "征集",
      "lead": "展签记录，骆道明造像属于北魏孝昌二年（526），来源为征集。",
      "paragraphs": [
        {
          "heading": "身份与来处",
          "text": "展签记录，骆道明造像属于北魏孝昌二年（526），来源为征集。骆道明造像的来源只记作征集，原始地点尚不清楚；石质佛教造像的形制先按现有照片记录。"
        },
        {
          "heading": "器形与工艺",
          "text": "器物本身，造像以供养人姓名和纪年标示发愿行为；石面雕刻佛像及相关尊像。 骆道明造像的裂隙、凿痕与边缘处理，保留了制作和长期使用的时间层。"
        },
        {
          "heading": "历史现场",
          "text": "造像供礼拜和发愿，题名中的供养人及孝昌二年纪年使一次地方佛教活动有了姓名与时间；征集来源则限制了对原寺院空间的复原。"
        }
      ],
