      "era": "北齐天保十年（559）",
      "material": "石质佛教造像碑",
      "provenance": "新郑市出土",
      "lead": "展签记录，刘绍安造像碑属于北齐天保十年（559），来源为新郑市出土。",
      "paragraphs": [
        {
          "heading": "身份与来处",
          "text": "展签记录，刘绍安造像碑属于北齐天保十年（559），来源为新郑市出土。读刘绍安造像碑上的文字，要把可辨字、残缺处和释读分层记录，不能用顺口的句子遮住缺损。"
        },
        {
          "heading": "器形与工艺",
          "text": "器物本身，文字和版面是其核心信息，现阶段只记录展签能够确认的题名与背景，未据模糊照片补写正文。 刘绍安造像碑的刻痕深浅、行款与残缺处比现代标点更接近原状，照片只呈现其中一部分。"
        },
        {
          "heading": "历史现场",
          "text": "这类造像碑服务于礼拜、追福和纪念，天保十年纪年把地方信仰放进北齐政权的时间框架；题记未清楚入镜的部分不据通行释文补写。"
        }
      ],
