      "number": 174,
      "title": "白陶帐座",
      "era": "隋开皇十五年（595）",
      "material": "陶质帷帐模型构件",
      "provenance": "1959年安阳市张盛墓出土",
      "lead": "展签记录，白陶帐座属于隋开皇十五年（595），来源为1959年安阳市张盛墓出土。",
      "paragraphs": [
        {
          "heading": "身份与来处",
          "text": "展签记录，白陶帐座属于隋开皇十五年（595），来源为1959年安阳市张盛墓出土。1959年安阳市张盛墓出土的出土信息把白陶帐座放回具体年代，陶质帷帐模型构件的器形与烧成线索仍需结合展签阅读。"
        },
        {
          "heading": "器形与工艺",
          "text": "器物本身，多件白陶座模拟帷帐支座，作为随葬模型重建室内陈设的一部分。 白陶帐座以多件立柱状构件模拟帷帐承托，截面和插接关系比单件外观更能说明它的模型功能。"
        },
        {
          "heading": "历史现场",
          "text": "白陶帐座固定帷帐立柱并在墓中模拟室内床帐，说明随葬模型也记录家具搭建方式。 仅凭白陶帐座的单件照片还不能锁定用途；遗址层位、磨损与残留物仍是下一步证据。"
        }
      ],
