      "era": "唐代（618—907）",
      "material": "唐三彩饮器",
      "provenance": "1976年郑州市后庄王村出土",
      "lead": "展签记录，三彩牛角形杯属于唐代（618—907），来源为1976年郑州市后庄王村出土。",
      "paragraphs": [
        {
          "heading": "身份与来处",
          "text": "展签记录，三彩牛角形杯属于唐代（618—907），来源为1976年郑州市后庄王村出土。三彩牛角形杯的来源记录指向1976年郑州市后庄王村，唐三彩饮器超出唐代（618—907）与现有照片的推断暂不展开。"
        },
        {
          "heading": "器形与工艺",
          "text": "器物本身，杯体呈弯曲兽角形，与中亚、西亚流行的来通杯相似，用于饮酒或宴饮陈设。 三彩牛角形杯的细部只有放回整组照片才有意义，局部纹理不能脱离器形单独解释。"
        },
        {
          "heading": "历史现场",
          "text": "三彩牛角形杯用于饮酒或宴席陈设，其来通式弯角轮廓说明唐代工匠在中亚、西亚器形基础上再创造。 关于三彩牛角形杯的出土组合仍不完整，能够确认的只到器形、材质与展签所示信息。"
        }
      ],
