      "id": "b-061",
      "number": 183,
      "title": "青釉环形鸡首瓷壶",
      "era": "隋代（581—618）",
      "material": "青釉瓷器",
      "provenance": "新乡市出土",
      "lead": "展签将青釉环形鸡首瓷壶定为隋代（581—618），来源记作新乡市出土。",
      "paragraphs": [
        {
          "heading": "身份与来处",
          "text": "展签将青釉环形鸡首瓷壶定为隋代（581—618），来源记作新乡市出土。青釉环形鸡首瓷壶属于青釉瓷器；青釉环形鸡首瓷壶的器形、青釉瓷器与出土组合互相补充，礼仪位置不能只从一处纹饰推出。"
        },
        {
          "heading": "器形与工艺",
          "text": "器物本身，器身形成闭合环形，并以鸡首作流，兼顾提握、注水与造型趣味。 看青釉环形鸡首瓷壶的轮廓和施彩部位，青釉瓷器的成型与装饰是两组线索，展签和照片分别留下依据。"
        },
        {
          "heading": "历史现场",
          "text": "鸡首作流，环形器身与提梁共同组织注水动作；这种奇巧造型把实用壶与动物装饰结合，反映隋代瓷器对早期鸡首壶传统的变体处理。"
        }
      ],
