      "lead": "展签记录，三彩鸳鸯尊属于唐代（618—907），来源为1974年新安县十里村出土。",
      "paragraphs": [
        {
          "heading": "身份与来处",
          "text": "展签记录，三彩鸳鸯尊属于唐代（618—907），来源为1974年新安县十里村出土。三彩鸳鸯尊放在1974年新安县十里村的历史层里看，唐三彩陶器的大小、开口和残留痕迹才有解释空间。"
        },
        {
          "heading": "器形与工艺",
          "text": "器形照片可见，三彩鸳鸯尊呈卧姿鸳鸯形器身，黄、绿、白褐等低温釉在表面交错。 沿着三彩鸳鸯尊的器壁、口沿和底部看，唐三彩陶器的泥胎怎样成型，1974年新安县十里村的照片给出了一条清楚线索。"
        },
        {
          "heading": "历史现场",
          "text": "鸳鸯形器身可盛液体或作为墓中陈设，动物轮廓主导观看方式；新安出土地点使三彩随葬器的地方使用有了依据。 三彩鸳鸯尊放在1974年新安县十里村的历史层里看，唐三彩陶器的大小、开口和残留痕迹才有解释空间。"
        }
      ],
