          "text": "展签记录，花釉瓷腰鼓标本属于唐代（618—907），来源为鲁山县段店窑址出土（展签照片略糊）。花釉瓷腰鼓标本留下了声音结构的线索，却不能脱离成组方式与演奏动作独自证明乐制。"
