      "paragraphs": [
        {
          "heading": "身份与来处",
          "text": "展签将鹤壁窑黑釉双龙瓷尊定为唐代（618—907），来源记作1985年鹤壁市出土。鹤壁窑黑釉双龙瓷尊属于黑釉瓷器；鹤壁窑黑釉双龙瓷尊的器形、黑釉瓷器与出土组合互相补充，礼仪位置不能只从一处纹饰推出。"
        },
        {
          "heading": "器形与工艺",
          "text": "器形照片可见，鹤壁窑黑釉双龙瓷尊呈高颈与鼓腹相接的尊形器，黑釉覆盖器身并显出局部露胎，成对龙形附饰。 把鹤壁窑黑釉双龙瓷尊放回1985年鹤壁市的记录，胎釉厚薄与器形转折共同说明黑釉瓷器的烧造特征。"
        },
        {
          "heading": "历史现场",
          "text": "双龙既作颈肩附饰，也提供对称的提携位置；鹤壁出土使这件黑釉尊成为本地窑业吸收唐代双龙瓶传统的参照。 1985年鹤壁市给鹤壁窑黑釉双龙瓷尊留下来源坐标，黑釉瓷器的纹样如何服务用途，要和同组器物对照。"
        }
      ],
