          "heading": "身份与来处",
          "text": "展签记录，嫦娥奔月纹铜镜属于唐代（618—907），郑州市出土。在同类器物中，铜镜一面磨光照容，另一面容纳神话、花鸟与狩猎图像，日用动作因而和吉祥观念相接。"
