      "paragraphs": [
        {
          "heading": "身份与来处",
          "text": "展签将白釉珍珠地《水龙吟》瓷枕定为宋代（960—1279），来源记作1986年三门峡市出土。白釉珍珠地《水龙吟》瓷枕属于诗文瓷枕；陶瓷枕既承托头部，又把诗词、人物和花鸟置于日常可见的平面，兼具寝具与图像载体两种身份。"
        },
        {
          "heading": "器形与工艺",
          "text": "器物本身，枕面以珍珠地衬托书写的《水龙吟》词文，实用寝具同时成为文学书写载体。 在1986年三门峡市的展柜光线下，看白釉珍珠地《水龙吟》瓷枕的诗文瓷枕表面层次，边缘和背面也要一起核对。"
        },
        {
          "heading": "历史现场",
          "text": "白釉珍珠地《水龙吟》瓷枕的历史意义在于，它为宋代词作传播、书写进入日用陶瓷和民间消费提供实物依据。 把白釉珍珠地《水龙吟》瓷枕的器形放回1986年三门峡市的出土背景，诗文瓷枕的装饰只是一条线索，组合信息还要继续核对。"
        }
      ],
