      "id": "b-101",
      "number": 223,
      "title": "白地黑花瓷梅瓶",
      "era": "宋代（960—1279）",
      "material": "磁州窑系瓷器",
      "provenance": "1985年镇平县出土",
      "lead": "展签记录，白地黑花瓷梅瓶属于宋代（960—1279），来源为1985年镇平县出土。",
      "paragraphs": [
        {
          "heading": "身份与来处",
          "text": "展签记录，白地黑花瓷梅瓶属于宋代（960—1279），来源为1985年镇平县出土。1985年镇平县出土的出土信息把白地黑花瓷梅瓶放回具体年代，磁州窑系瓷器的器形与烧成线索仍需结合展签阅读。"
        },
        {
          "heading": "器形与工艺",
          "text": "器形照片可见，白地黑花瓷梅瓶呈小口短颈、丰肩和下收腹，白色化妆土上绘黑彩。 在1985年镇平县的展柜光线下，看白地黑花瓷梅瓶的磁州窑系瓷器表面层次，边缘和背面也要一起核对。"
        },
        {
          "heading": "历史现场",
          "text": "梅瓶小口丰肩，适于贮酒并减少挥发，黑彩装饰集中在宽阔肩腹；镇平出土使宋代白地黑花器的地区使用可被定位。 白地黑花瓷梅瓶的用途要结合1985年镇平县与同组材料判断，先从磁州窑系瓷器的器形和磨痕读起。"
        }
      ],
