      "title": "青花无双谱人物诗文瓷瓶",
      "era": "清代",
      "material": "青花诗文瓷器",
      "provenance": "河南博物院藏",
      "lead": "展签记录，青花无双谱人物诗文瓷瓶属于清代，来源为河南博物院藏。",
      "paragraphs": [
        {
          "heading": "身份与来处",
          "text": "展签记录，青花无双谱人物诗文瓷瓶属于清代，来源为河南博物院藏。河南博物院藏的出土信息把青花无双谱人物诗文瓷瓶放回具体年代，青花诗文瓷器的器形与烧成线索仍需结合展签阅读。"
        },
        {
          "heading": "器形与工艺",
          "text": "器物本身，瓶身将《无双谱》人物、姓名和题诗组合成连续装饰，器物用于陈设，也承担识人读史的图像功能。 在河南博物院藏的展柜光线下，看青花无双谱人物诗文瓷瓶的青花诗文瓷器表面层次，边缘和背面也要一起核对。"
        },
        {
          "heading": "历史现场",
          "text": "瓶身将人物、姓名和诗文连续排布，主要服务于陈设和识读；《无双谱》题材把历史人物评价带进清代居室观看。 从河南博物院藏的材料出发，青花无双谱人物诗文瓷瓶的青花诗文瓷器纹饰可作观察入口，不能独自承担用途判断。"
        }
      ],
