      "id": "b-123",
      "number": 245,
      "title": "镂孔龙纹铜俎",
      "era": "春秋（前770—前476）",
      "material": "青铜承肉食器",
      "provenance": "1978年淅川县下寺楚国墓地M2出土",
      "lead": "展签记录，镂孔龙纹铜俎属于春秋（前770—前476），来源为1978年淅川县下寺楚国墓地M2出土。",
      "paragraphs": [
        {
          "heading": "身份与来处",
          "text": "展签记录，镂孔龙纹铜俎属于春秋（前770—前476），来源为1978年淅川县下寺楚国墓地M2出土。镂孔龙纹铜俎在1978年淅川县下寺楚国墓地M2留下的组合线索，能约束青铜承肉食器在礼仪中的位置，单一纹饰只提供观察入口。"
        },
        {
          "heading": "器形与工艺",
          "text": "器物本身，俎面由长方平台和足部构成，镂孔龙纹兼具减重与装饰作用；宴飨时可承放肉食。 对照1978年淅川县下寺楚国墓地M2的出土信息，镂孔龙纹铜俎的纹带转折与边缘修整让青铜承肉食器的铸造过程有了可观察的层次。"
        },
        {
          "heading": "历史现场",
          "text": "镂孔龙纹铜俎在宴飨中承放切割后的肉食，镂孔龙纹使实际承案兼具楚式礼器装饰。 镂孔龙纹铜俎在1978年淅川县下寺楚国墓地M2留下的组合线索，能约束青铜承肉食器在礼仪中的位置，单一纹饰只提供观察入口。"
        }
      ],
