      "lead": "展签记录，黄釉蓝彩九桃纹瓷盘属于清乾隆（1736—1795），来源为征集。",
      "paragraphs": [
        {
          "heading": "身份与来处",
          "text": "展签记录，黄釉蓝彩九桃纹瓷盘属于清乾隆（1736—1795），来源为征集。黄釉蓝彩九桃纹瓷盘的来源只记作征集，原始地点尚不清楚；釉上彩瓷器的胎釉和器形以展签为界。"
        },
        {
          "heading": "器形与工艺",
          "text": "器物照片可见，黄釉蓝彩九桃纹瓷盘呈浅腹圆盘和圈足，黄釉地上以蓝彩作画，九桃纹。 在征集记录的展柜光线下，看黄釉蓝彩九桃纹瓷盘的釉上彩瓷器表面层次，边缘和背面也要一起核对。"
        },
        {
          "heading": "历史现场",
          "text": "盘可供宴席盛物或室内陈设，九桃集中表达祝寿意味；黄地蓝彩的强烈对比使吉祥主题适合正面展示。 黄釉蓝彩九桃纹瓷盘放在征集记录的历史层里看，釉上彩瓷器的大小、开口和残留痕迹才有解释空间。"
        }
      ],
