          "text": "展签记录，粉彩云蝠纹瓷盘属于清代（1644—1911），来源为征集。粉彩云蝠纹瓷盘的来源只记作征集，原始地点尚不清楚；粉彩瓷器的胎釉和器形以展签为界。"
