          "text": "展签记录，斗彩云龙纹瓷盖罐属于清代（1644—1911），来源为征集。斗彩云龙纹瓷盖罐的来源只记作征集，原始地点尚不清楚；斗彩瓷器的胎釉和器形以展签为界。"
