        {
          "heading": "身份与来处",
          "text": "展签记录，黄釉粉彩云龙纹瓷豆属于清光绪（1875—1908），来源为征集。黄釉粉彩云龙纹瓷豆的器形、官窑粉彩瓷器与出土组合互相补充，礼仪位置不能只从一处纹饰推出。"
        },
        {
          "heading": "器形与工艺",
          "text": "器物本身，黄釉地上以粉彩绘云龙，器形仿古代豆；底部款识表明光绪官窑背景。 黄釉粉彩云龙纹瓷豆的器壁曲线把胎体和釉色连在一起，征集记录留下的官窑粉彩瓷器细部宜从正面、侧面合看。"
        },
        {
          "heading": "历史现场",
          "text": "器形仿古豆，主要用于礼仪式陈设而非恢复先秦盛食方式；光绪款、黄地粉彩和云龙纹共同说明晚清对古礼器轮廓的再造。 对黄釉粉彩云龙纹瓷豆而言，器形先于寓意，征集记录与官窑粉彩瓷器的同组线索共同限定可以说到哪一步。"
        }
