      "id": "b-138",
      "number": 260,
      "title": "青花梵文莲瓣洗",
      "era": "明万历（1572—1620）",
      "material": "官窑青花瓷器",
      "provenance": "征集",
      "lead": "展签记录，青花梵文莲瓣洗属于明万历（1572—1620），来源为征集。",
      "paragraphs": [
        {
          "heading": "身份与来处",
          "text": "展签记录，青花梵文莲瓣洗属于明万历（1572—1620），来源为征集。青花梵文莲瓣洗的来源只记作征集，原始地点尚不清楚；官窑青花瓷器的胎釉和器形以展签为界。"
        },
        {
          "heading": "器形与工艺",
          "text": "器物本身，洗作莲瓣形，青花书写梵文；底足双圈内有六字年款，器形与文字共同服务于佛教语境。 在征集记录的展柜光线下，看青花梵文莲瓣洗的官窑青花瓷器表面层次，边缘和背面也要一起核对。"
        },
        {
          "heading": "历史现场",
          "text": "莲瓣洗可盛净水或作供奉陈设，梵文使使用环境带有佛教意味；万历款为年代线索，但具体寺院或宫廷归属因征集来源而未知。"
        }
      ],
