      "era": "清康熙（1662—1722）",
      "material": "红釉瓷器",
      "provenance": "征集",
      "lead": "展签记录，郎窑红釉瓷盘属于清康熙（1662—1722），来源为征集。",
      "paragraphs": [
        {
          "heading": "身份与来处",
          "text": "展签记录，郎窑红釉瓷盘属于清康熙（1662—1722），来源为征集。郎窑红釉瓷盘的来源只记作征集，原始地点尚不清楚；红釉瓷器的胎釉和器形以展签为界。"
        },
        {
          "heading": "器形与工艺",
          "text": "器物为浅腹圆盘和圈足，通体施红釉，口沿与弧面转折处显出深浅变化。 在征集记录的展柜光线下，看郎窑红釉瓷盘的红釉瓷器表面层次，边缘和背面也要一起核对。"
        },
        {
          "heading": "历史现场",
          "text": "盘可盛物或陈设，单色红釉要求烧成时控制铜红呈色；征集信息没有原使用环境，因此这件作品更适合讨论康熙时期的釉色技术。"
        }
      ],
