          "heading": "身份与来处",
          "text": "展签记录，霁蓝釉瓷盘属于清康熙（1662—1722），来源为征集。霁蓝釉瓷盘的来源只记作征集，原始地点尚不清楚；蓝釉瓷器的胎釉和器形以展签为界。"
