      "id": "supp-qing-enamel-jade-gourd",
      "number": 275,
      "title": "珐琅镶玉葫芦",
      "era": "清乾隆",
      "material": "錾胎珐琅嵌玉陈设器",
      "provenance": "河南博物院征集",
      "lead": "这件清代陈设器高66厘米，上下两腹组成葫芦，盖口藏在缠绕的藤蔓之中。",
      "paragraphs": [
        {
          "heading": "身份与来处",
          "text": "这件清代陈设器高66厘米，上下两腹组成葫芦，盖口藏在缠绕的藤蔓之中。底部“大清乾隆年制”六字錾款给出时代线索；葫芦又借“福禄”谐音，成为适合祝颂与陈设的器形。"
        },
        {
          "heading": "器形与工艺",
          "text": "铜胎表面先錾出藤、叶、花与细密珍珠地，再在花叶内填入蓝、绿、粉等珐琅釉。四十三枚白玉小葫芦嵌在枝叶之间，乳白玉色从浓重底色中凸出；圈足以蓝黄相间的连续纹收束，材质和色彩直到最下端仍没有中断。"
        },
        {
          "heading": "历史现场",
          "text": "它把金属錾刻、珐琅烧造与玉石镶嵌放进同一件器物，观看顺序也随之改变：先认出整体葫芦，再在藤叶间逐枚寻找更小的葫芦。层层重复的“福禄”意象与复合工艺相互加强，显示清代宫廷式工艺对材料、吉语和视觉密度的共同追求。"
        }
      ],
